(1, 'ec1960010f94734dd47fe4b4804440c8', NULL, 'cs', 1, 'page', 'o-nas', NULL, 'O nás', 'krátký úvod', 'test blaldlkj', 1, 1, 0, '2026-09-28 20:09:31'),
