  `active_product_key` char(32) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `language` char(2) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `revision_number` int(10) UNSIGNED NOT NULL,
