INSERT INTO `product_revisions` (`id`, `product_key`, `active_product_key`, `language`, `revision_number`, `slug`, `active_slug`, `name`, `brand`, `summary`, `description`, `details_json`, `category`, `subcategory`, `price_czk`, `image_path`, `sizes`, `stock_status`, `published`, `saved_at`) VALUES
(1, '93c343c0373958a84130725d76e54240', NULL, 'cs', 1, 'terraventure-5-men', NULL, 'Topo Athletic Terraventure 5 Men\'s', 'Topo Athletic', 'Trailové boty Topo patří mezi jedny z nejoblíbenějších na dálkových trecích.', 'Prodyšné a odolné trailové boty na turistiku, běh i dálkové treky. Široká špička dává prstům prostor, přilnavá podešev drží v terénu a ochranný plát Rock Plate pomáhá na kamenitých stezkách.\r\n\r\n\r\nNa stezku s lehkým krokem\r\nPátá generace Terraventure má odolnější tkaný svršek s dvojí hustotou úpletu a nenasákavé vložky FKT Insole. Pěna ZipFoam™ tlumí došlap, zatímco Rock Plate chrání chodidla před ostrými kameny.\r\n\r\nCo na nich oceníte\r\nProstorná špička pro přirozený pohyb prstů\r\nVibram® Megagrip pro přilnavost na mokrém podkladu\r\nProdyšný a odolný svršek\r\nFKT Insole pro rychlejší schnutí\r\nMožnost uchycení návleků na suchý zip\r\nVhodné pro turistiku, trailový běh a dálkové treky\r\nParametry\r\nDrop	3 mm\r\nTlumení pod špičkou	22 mm\r\nTlumení pod patou	25 mm\r\nHmotnost	292 g (jedna bota, 42,5 EU)\r\nPodešev	Vibram® Megagrip\r\nDostupnost dopravy	Ukázka dopravy zdarma, způsob doručení bude upřesněn v e-shopu.\r\nJak vybrat šířku\r\nUž standardní verze Topo Athletic nabízí více prostoru v přední části boty než běžný úzký střih. Pokud potřebujete ještě větší prostor, hledejte variantu Wide; tato ukázka zobrazuje barvu Grey / Clay ve standardní šířce. Rozměry chodidla si před nákupem ověřte v tabulce výrobce.\r\n\r\n← Zpět na všechny produkty', NULL, 'boty', '', 2000, 'https://gramino.cz/wp-content/uploads/2024/11/Topo-Athletic-Terraventure-4-Men-trailove-boty-panske-Dark-Grey-Green-03.webp', '42', 'in_stock', 1, '2026-09-28 20:48:27'),
(2, '93c343c0373958a84130725d76e54240', NULL, 'cs', 2, 'terraventure-5-men', NULL, 'Topo Athletic Terraventure 5 Men\'s', 'Topo Athletic', 'Trailové boty Topo patří mezi jedny z nejoblíbenějších na dálkových trecích.', '      <p class=\"product-brand\">Topo Athletic · Trailové boty</p>\r\n        <h1>Topo Athletic Terraventure 5 Men\'s</h1>\r\n        <div class=\"detail-flags\"><span>3 mm drop</span><span>Vibram® Megagrip</span><span>Široká špička</span></div>\r\n        <p class=\"detail-lead\">Prodyšné a odolné trailové boty na turistiku, běh i dálkové treky. Široká špička dává prstům prostor, přilnavá podešev drží v terénu a ochranný plát Rock Plate pomáhá na kamenitých stezkách.</p>\r\n        <label class=\"field-label\">Barva</label><span class=\"variant-chip\">Grey / Clay</span>\r\n        <label class=\"field-label\" for=\"shoe-size\">Velikost produktu</label>\r\n        <select id=\"shoe-size\" name=\"size\" required><option value=\"\">Vyberte velikost</option><option>42 EU</option><option selected>42,5 EU</option><option>43 EU</option><option>44 EU</option><option>45 EU</option></select>\r\n        <div class=\"detail-price\"><strong>3 990 Kč</strong><span class=\"stock\"><span class=\"stock-dot\" aria-hidden=\"true\"></span>Skladem</span></div>\r\n        <div class=\"buy-row\"><div class=\"quantity\" aria-label=\"Počet kusů\"><button type=\"button\" id=\"minus\" aria-label=\"Ubrat kus\">−</button><output id=\"qty\">1</output><button type=\"button\" id=\"plus\" aria-label=\"Přidat kus\">+</button></div><button class=\"detail-add\" type=\"button\" id=\"detail-add\">Přidat do košíku</button></div>\r\n        <p class=\"detail-feedback\" id=\"detail-feedback\" role=\"status\" aria-live=\"polite\"></p>\r\n        <div class=\"detail-help\"><a href=\"#velikosti\">Tabulka velikostí</a><a href=\"#parametry\">Parametry a doručení</a></div>\r\n      </div>\r\n    </div>\r\n    <section class=\"story\" aria-labelledby=\"story-title\">\r\n      <h2 id=\"story-title\">Na stezku s lehkým krokem</h2>\r\n      <p>Pátá generace Terraventure má odolnější tkaný svršek s dvojí hustotou úpletu a nenasákavé vložky FKT Insole. Pěna ZipFoam™ tlumí došlap, zatímco Rock Plate chrání chodidla před ostrými kameny.</p>\r\n      <div class=\"story-grid\">\r\n        <div><h3>Co na nich oceníte</h3><ul class=\"feature-list\"><li>Prostorná špička pro přirozený pohyb prstů</li><li>Vibram® Megagrip pro přilnavost na mokrém podkladu</li><li>Prodyšný a odolný svršek</li><li>FKT Insole pro rychlejší schnutí</li><li>Možnost uchycení návleků na suchý zip</li><li>Vhodné pro turistiku, trailový běh a dálkové treky</li></ul></div>\r\n        <div id=\"parametry\"><h3>Parametry</h3><table class=\"spec-table\"><tbody><tr><th>Drop</th><td>3 mm</td></tr><tr><th>Tlumení pod špičkou</th><td>22 mm</td></tr><tr><th>Tlumení pod patou</th><td>25 mm</td></tr><tr><th>Hmotnost</th><td>292 g (jedna bota, 42,5 EU)</td></tr><tr><th>Podešev</th><td>Vibram® Megagrip</td></tr><tr><th>Dostupnost dopravy</th><td>Ukázka dopravy zdarma, způsob doručení bude upřesněn v e-shopu.</td></tr></tbody></table></div>\r\n      </div>\r\n      <h3 id=\"velikosti\">Jak vybrat šířku</h3><p>Už standardní verze Topo Athletic nabízí více prostoru v přední části boty než běžný úzký střih. Pokud potřebujete ještě větší prostor, hledejte variantu Wide; tato ukázka zobrazuje barvu Grey / Clay ve standardní šířce. Rozměry chodidla si před nákupem ověřte v tabulce výrobce.</p>\r\n      <p><a href=\"/simple-store/index.php#produkty\">← Zpět na všechny produkty</a></p>', NULL, 'boty', '', 2000, 'https://gramino.cz/wp-content/uploads/2024/11/Topo-Athletic-Terraventure-4-Men-trailove-boty-panske-Dark-Grey-Green-03.webp', '42', 'in_stock', 1, '2026-09-28 20:53:15'),
(3, '93c343c0373958a84130725d76e54240', NULL, 'cs', 3, 'terraventure-5-men', NULL, 'Topo Athletic Terraventure 5 Men\'s', 'Topo Athletic', 'Trailové boty Topo patří mezi jedny z nejoblíbenějších na dálkových trecích.', 'Prodyšné a odolné trailové boty na turistiku, běh i dálkové treky. Široká špička dává prstům prostor, přilnavá podešev drží v terénu a ochranný plát Rock Plate pomáhá na kamenitých stezkách.\r\n\r\n\r\nNa stezku s lehkým krokem\r\nPátá generace Terraventure má odolnější tkaný svršek s dvojí hustotou úpletu a nenasákavé vložky FKT Insole. Pěna ZipFoam™ tlumí došlap, zatímco Rock Plate chrání chodidla před ostrými kameny.\r\n\r\nCo na nich oceníte\r\nProstorná špička pro přirozený pohyb prstů\r\nVibram® Megagrip pro přilnavost na mokrém podkladu\r\nProdyšný a odolný svršek\r\nFKT Insole pro rychlejší schnutí\r\nMožnost uchycení návleků na suchý zip\r\nVhodné pro turistiku, trailový běh a dálkové treky\r\nParametry\r\nDrop	3 mm\r\nTlumení pod špičkou	22 mm\r\nTlumení pod patou	25 mm\r\nHmotnost	292 g (jedna bota, 42,5 EU)\r\nPodešev	Vibram® Megagrip\r\nDostupnost dopravy	Ukázka dopravy zdarma, způsob doručení bude upřesněn v e-shopu.\r\nJak vybrat šířku\r\nUž standardní verze Topo Athletic nabízí více prostoru v přední části boty než běžný úzký střih. Pokud potřebujete ještě větší prostor, hledejte variantu Wide; tato ukázka zobrazuje barvu Grey / Clay ve standardní šířce. Rozměry chodidla si před nákupem ověřte v tabulce výrobce.\r\n\r\n← Zpět na všechny produkty', NULL, 'boty', '', 2000, 'https://gramino.cz/wp-content/uploads/2024/11/Topo-Athletic-Terraventure-4-Men-trailove-boty-panske-Dark-Grey-Green-03.webp', '42', 'in_stock', 1, '2026-09-28 20:54:55'),
