INSERT INTO `product_revisions` (`id`, `product_key`, `active_product_key`, `language`, `revision_number`, `slug`, `active_slug`, `name`, `brand`, `summary`, `description`, `details_json`, `category`, `subcategory`, `price_czk`, `image_path`, `sizes`, `stock_status`, `published`, `saved_at`) VALUES
(159, '93c343c0373958a84130725d76e54240', NULL, 'cs', 40, 'terraventure-5-men', NULL, 'Topo Athletic Terraventure 5 Men\'s', 'Topo Athletic', 'Trailové boty Topo patří mezi jedny z nejoblíbenějších na dálkových trecích.', 'Prodyšné a odolné trailové boty na turistiku, běh i dálkové treky. Široká špička dává prstům prostor, přilnavá podešev drží v terénu a ochranný plát Rock Plate pomáhá na kamenitých stezkách.', '{\"options\":[{\"name\":\"Velikost\",\"values\":[\"42\",\"43\"]},{\"name\":\"Barva\",\"values\":[\"Dark Grey \\/ Green\",\"Blue\"]}],\"specifications\":[{\"name\":\"Hmotnost\",\"value\":\"400 g\"},{\"name\":\"Nový parametr\",\"value\":\"Doplňte hodnotu\"}],\"sections\":[{\"type\":\"text\",\"heading\":\"Na stezku s lehkým krokem\",\"body\":\"Pátá generace Terraventure má odolnější tkaný svršek s dvojí hustotou úpletu a nenasákavé vložky FKT Insole. Pěna ZipFoam™ tlumí došlap, zatímco Rock Plate chrání chodidla před ostrými kameny.\"},{\"type\":\"list\",\"heading\":\"Co na nich oceníte\",\"body\":\"Prostorná špička pro přirozený pohyb prstů\\nVibram® Megagrip pro přilnavost na mokrém podkladu\\nProdyšný a odolný svršek\\nFKT Insole pro rychlejší schnutí\\nMožnost uchycení návleků na suchý zip\\nVhodné pro turistiku, trailový běh a dálkové treky\"},{\"type\":\"text\",\"heading\":\"Jak vybrat šířku\",\"body\":\"Už standardní verze Topo Athletic nabízí více prostoru v přední části boty než běžný úzký střih. Pokud potřebujete ještě větší prostor, hledejte variantu Wide; tato ukázka zobrazuje barvu Grey \\/ Clay ve standardní šířce. Rozměry chodidla si před nákupem ověřte v tabulce výrobce.\"},{\"type\":\"table\",\"heading\":\"Parametry\",\"body\":\"Název | Hodnota \\nDrop | 3 mm\\nTlumení pod špičkou | 22 mm\\nTlumení pod patou |25 mm\\nHmotnost |292 g\\nPodešev\\tVibram® | Megagrip\"}],\"gallery\":[\"images\\/media\\/products\\/93c343c0373958a84130725d76e54240\\/topo-athletic-terraventure-5-men-grey-clay--87b69fbf67b6801e4e0cc8ab.jpg\",\"images\\/media\\/products\\/93c343c0373958a84130725d76e54240\\/topo-athletic-terraventure-5-men-grey-clay--a9c1b03071ceeffb8f29bf98.jpg\",\"images\\/media\\/products\\/93c343c0373958a84130725d76e54240\\/topo-athletic-terraventure-5-men-grey-clay--d167ae3777c8cacd0b5417c1.jpg\",\"images\\/media\\/products\\/93c343c0373958a84130725d76e54240\\/topo-athletic-terraventure-5-men-grey-clay--e07ab23c0def43ccc0595378.jpg\",\"images\\/media\\/products\\/93c343c0373958a84130725d76e54240\\/topo-athletic-terraventure-5-men-grey-clay--4433c1786e0b10c70ba93b00.jpg\"]}', 'boty', 'panske-trailove-boty', 2000, 'images/media/products/93c343c0373958a84130725d76e54240/topo-athletic-terraventure-5-men-grey-clay--f19a4bb1d807fb3ba4ebe69b.jpg', '', 'in_stock', 1, '2026-10-03 04:36:05'),
